-- Standardise the Course Info tabs of every non-WSQ (C-prefix) course (SG):
-- Prerequisite | Minimum Entry Requirement | Minimum Software/Hardware Requirement (+ exam-info extras).
-- No prerequisite -> "This course is for beginners. No prerequisite is required." Missing software tab -> laptop + browser.
-- Funding / grant / UTAP / SkillsFuture / WSQ / CITREP+ / promo / appeal / note / mode-of-training / target-audience sections dropped.
-- Built from the LIVE value (store override if any); written to store 0, override removed. MD5-guarded: a row edited
-- after the export is left untouched. Idempotent (a re-run matches no MD5).
SET @ok := ((SELECT COUNT(*) FROM core_store WHERE store_id = 1 AND code = 'singapore') = 1);
SET @a := (SELECT attribute_id FROM eav_attribute WHERE entity_type_id = 4 AND attribute_code = 'prerequisite');
DROP TEMPORARY TABLE IF EXISTS tmp_prereq_std;
CREATE TEMPORARY TABLE tmp_prereq_std (sku VARCHAR(64) NOT NULL PRIMARY KEY, val MEDIUMTEXT NOT NULL,
  md5_0 CHAR(32) NOT NULL, md5_ov CHAR(32) NOT NULL) DEFAULT CHARSET = utf8;
INSERT INTO tmp_prereq_std (sku, val, md5_0, md5_ov) VALUES
('C009', '<h2>Prerequisite</h2>\n<p>This course is for beginners. No prerequisite is required.</p>\n<h2>Minimum Entry Requirement</h2>\n<p>Knowledge and Skills</p>\n<ul>\n<li>Able to operate using computer functions</li>\n<li>Minimum 3 GCE &lsquo;O&rsquo; Levels Passes including English or WPL Level 5 (Average of Reading, Listening, Speaking &amp; Writing Scores)</li>\n</ul>\n<p>Attitude</p>\n<ul>\n<li>Positive Learning Attitude</li>\n<li>Enthusiastic Learner</li>\n</ul>\n<p>Experience</p>\n<ul>\n<li>Minimum of 1 year of working experience.</li>\n</ul>\n<p>Target Age Group: 18-65 years old</p>\n<h2>Minimum Software/Hardware Requirement</h2>\n<p><strong>Software:</strong></p>\n<p>TBD</p>\n<p><strong>Hardware:</strong>&nbsp;Window or Mac Laptops</p>\n', '5fd50c0d3565b26f2fc3b3b913697675', ''),
