('C1091', '<h2>Prerequisite</h2>\n<ul>\n<li>\n<p>Basic IT Literacy skills Basic IT Literacy &ndash; Refers to skills required to operate at the user level a graphical operating system environment such as Microsoft Windows&reg; or Linux Ubuntu&reg;, performing basic operating commands such as launching an application, copying and pasting information, using menus, windows and peripheral devices such as mouse and keyboard. Additionally, users should be familiar with internet browsers, search engines, page navigation, and forms.</p>\n</li>\n</ul>\n<h2>Minimum Entry Requirement</h2>\n<p>Knowledge and Skills</p>\n<ul>\n<li>Able to operate using computer functions</li>\n<li>Minimum 3 GCE &lsquo;O&rsquo; Levels Passes including English or WPL Level 5 (Average of Reading, Listening, Speaking &amp; Writing Scores)</li>\n</ul>\n<p>Attitude</p>\n<ul>\n<li>Positive Learning Attitude</li>\n<li>Enthusiastic Learner</li>\n</ul>\n<p>Experience</p>\n<ul>\n<li>Minimum of 1 year of working experience.</li>\n</ul>\n<p>Target Age Group: 18-65 years old</p>\n<h2>Minimum Software/Hardware Requirement</h2>\n<p><strong>Software:</strong></p>\n<p>You will need the following for this course:</p>\n<ul>\n<li>A web browser such as Google Chrome, Microsoft Edge or Safari &ndash; free</li>\n<li>Access to the course materials provided in class</li>\n</ul>\n<p><strong>Hardware:</strong> Windows PC or Mac laptop</p>\n', 'a56e34f1bba2cb45594e164e69c79bad', ''),
('C1097', '<h2>Prerequisite</h2>\n<p>This course is for beginners. No prerequisite is required.</p>\n<h2>Minimum Entry Requirement</h2>\n<p>Knowledge and Skills</p>\n<ul>\n<li>Able to operate using computer functions</li>\n<li>Minimum 3 GCE &lsquo;O&rsquo; Levels Passes including English or WPL Level 5 (Average of Reading, Listening, Speaking &amp; Writing Scores)</li>\n</ul>\n<p>Attitude</p>\n<ul>\n<li>Positive Learning Attitude</li>\n<li>Enthusiastic Learner</li>\n</ul>\n<p>Experience</p>\n<ul>\n<li>Minimum of 1 year of working experience.</li>\n</ul>\n<p>Target Age Group: 18-65 years old</p>\n<h2>Minimum Software/Hardware Requirement</h2>\n<p><strong>Software:</strong></p>\n<ul>\n<li>Microsoft Excel for Microsoft 365 (Windows) with Power Query and Power Pivot&nbsp;<a href="https://www.microsoft.com/en-sg/microsoft-365/excel" title="Microsoft Excel" target="_blank">https://www.microsoft.com/en-sg/microsoft-365/excel</a></li>\n</ul>\n<p><strong>Hardware:</strong>&nbsp;Windows laptop (Power Pivot is not available in Excel for Mac)</p>\n', 'f17055e9f17706f844965573e5e43189', ''),
('C1098', '<h2>Prerequisite</h2>\n<p>This course is for beginners. No prerequisite is required.</p>\n<h2>Minimum Entry Requirement</h2>\n<p>Knowledge and Skills</p>\n<ul>\n<li>Able to operate using computer functions</li>\n<li>Minimum 3 GCE &lsquo;O&rsquo; Levels Passes including English or WPL Level 5 (Average of Reading, Listening, Speaking &amp; Writing Scores)</li>\n<li>Working knowledge of Python or TypeScript, REST APIs and the command line</li>\n</ul>\n<p>Attitude</p>\n<ul>\n<li>Positive Learning Attitude</li>\n<li>Enthusiastic Learner</li>\n</ul>\n<p>Experience</p>\n<ul>\n<li>Minimum of 1 year of working experience.</li>\n</ul>\n<p>Target Age Group: 18-65 years old</p>\n<h2>Minimum Software/Hardware Requirement</h2>\n<p><strong>Software:</strong></p>\n<p>You will need the following for this course:</p>\n<ul>\n<li><a href="https://platform.claude.com/" target="_blank">A Claude Developer Platform account with API credits</a> &ndash; required for the Claude API and Agent SDK labs (pay as you go)</li>\n<li><a href="https://claude.ai/" target="_blank">A Claude Pro (or higher) subscription</a> &ndash; required for Claude Code</li>\n<li><a href="https://www.python.org/downloads/" target="_blank">Python 3.10 or later</a> &ndash; free</li>\n<li><a href="https://nodejs.org/" target="_blank">Node.js (LTS)</a> &ndash; free, for the TypeScript and MCP server labs</li>\n<li><a href="https://code.visualstudio.com/" target="_blank">Visual Studio Code</a> &ndash; free</li>\n</ul>\n<p><strong>Hardware:</strong> Windows PC or Mac laptop</p>\n', 'e37d1308c157c3cff31ae7e1b732806a', ''),
('C11', '<h2>Prerequisite</h2>\n<p>This course is for beginners. No prerequisite is required.</p>\n<h2>Minimum Entry Requirement</h2>\n<p>Knowledge and Skills</p>\n<ul>\n<li>Able to operate using computer functions</li>\n<li>Minimum 3 GCE ‘O’ Levels Passes including English or WPL Level 5 (Average of Reading, Listening, Speaking &amp; Writing Scores)</li>\n</ul>\n<p>Attitude</p>\n<ul>\n<li>Positive Learning Attitude</li>\n<li>Enthusiastic Learner</li>\n</ul>\n<p>Experience</p>\n<ul>\n<li>Minimum of 1 year of working experience.</li>\n</ul>\n<p>Target Age Group: 21-65 years old</p>\n<h2>Minimum Software/Hardware Requirement</h2>\n<p><strong>Software:</strong></p>\n<p>You will need the following for this course:</p>\n<ul>\n<li>A free account on a generative AI assistant of your choice, e.g. <a href="https://chatgpt.com/" target="_blank">ChatGPT</a>, <a href="https://gemini.google.com/" target="_blank">Google Gemini</a> or <a href="https://copilot.microsoft.com/" target="_blank">Microsoft Copilot</a> (the free tier is sufficient)</li>\n<li><a href="https://accounts.google.com/signup" target="_blank">A free Google account</a></li>\n<li><a href="https://search.google.com/search-console" target="_blank">Google Search Console</a> &ndash; free</li>\n<li><a href="https://analytics.google.com/" target="_blank">Google Analytics</a> &ndash; free</li>\n</ul>\n<p><strong>Hardware:</strong> Windows PC or Mac laptop</p>\n', '3d22cfe4bdbfb14f026c3ca347e0daaf', ''),
