('C34', '<h2>Prerequisite</h2>\n<p>This course is for beginners. No prerequisite is required.</p>\n<h2>Minimum Entry Requirement</h2>\n<p>Knowledge and Skills</p><ul><li>Able to operate using computer functions</li><li>Minimum 3 GCE ‘O’ Levels Passes including English or WPL Level 5 (Average of Reading, Listening, Speaking &amp; Writing Scores)</li></ul><p>Attitude</p><ul><li>Positive Learning Attitude</li><li>Enthusiastic Learner</li></ul><p>Experience</p><ul><li>Minimum of 1 year of working experience.</li></ul><p>Target Age Group: 21-65 years old</p>\n<h2>Minimum Software/Hardware Requirement</h2>\n<p><strong>Software:</strong></p><p>You will need the following for this course:</p><ul><li>Microsoft 365 Copilot – a training account will be provided</li></ul><p><strong>Hardware:</strong> Windows PC or Mac laptop</p><ul><li>The staff will send you an invoice with the fee breakdown.</li><li>Login to the <u><a href="https://www.myskillsfuture.gov.sg/content/portal/en/index.html" rel="noopener noreferrer" target="_blank">MySkillsFuture portal</a></u>, select the course you’re enrolling on and enter the course date and schedule.</li><li>Enter the course fee payable by you (including GST) and enter the amount of credit to claim.</li><li>Upload your invoice and click ‘Submit’</li></ul>\n', 'eaa74de0a03c3b892904f0f8d4980c61', ''),
('C348', '<h2>Prerequisite</h2>\n<p>This course is for beginners. No prerequisite is required.</p>\n<h2>Minimum Entry Requirement</h2>\n<p>Knowledge and Skills</p>\n<ul>\n<li>Able to operate using computer functions</li>\n<li>Minimum 3 GCE &lsquo;O&rsquo; Levels Passes including English or WPL Level 5 (Average of Reading, Listening, Speaking &amp; Writing Scores)</li>\n</ul>\n<p>Attitude</p>\n<ul>\n<li>Positive Learning Attitude</li>\n<li>Enthusiastic Learner</li>\n</ul>\n<p>Experience</p>\n<ul>\n<li>Minimum of 1 year of working experience.</li>\n</ul>\n<p>Target Age Group: 18-65 years old</p>\n<h2>Minimum Software/Hardware Requirement</h2>\n<p><strong>Software:</strong></p>\n<p>You will need the following for this course:</p>\n<ul>\n<li>A web browser such as Google Chrome, Microsoft Edge or Safari &ndash; free</li>\n<li>Access to the course materials provided in class</li>\n</ul>\n<p><strong>Hardware:</strong> Windows PC or Mac laptop</p>\n<h2>PeopleCert Exam Voucher</h2>\n<p>1: Visit <span style="text-decoration: underline;"><a href="https://www.peoplecert.org/" title="ITIL4 Exam Voucher" target="_blank">https://www.peoplecert.org/</a></span><br />2: Create your PeopleCert Account. If you already have one, please sign in.<br />3: Enter the PeopleCert Voucher Code provided to you. Access your eBook in the My eBooks tab and Schedule your Exam in the Overview tab.<br />4: Access your training in My Trainings tab.</p>\n', 'fba23a8ac0f6b484ff86038d0e37b829', ''),
