('C603', '<h2>Prerequisite</h2>\n<p>This is an intermediate course. Participants should have basic knowledge on the following subjects:</p>\n<ul>\n<li>HTML</li>\n<li>CSS</li>\n<li>Javascript</li>\n<li>ES6 or Typescript</li>\n</ul>\n<h2>Minimum Entry Requirement</h2>\n<p>Knowledge and Skills</p>\n<ul>\n<li>Able to operate using computer functions</li>\n<li>Minimum 3 GCE &lsquo;O&rsquo; Levels Passes including English or WPL Level 5 (Average of Reading, Listening, Speaking &amp; Writing Scores)</li>\n</ul>\n<p>Attitude</p>\n<ul>\n<li>Positive Learning Attitude</li>\n<li>Enthusiastic Learner</li>\n</ul>\n<p>Experience</p>\n<ul>\n<li>Minimum of 1 year of working experience.</li>\n</ul>\n<p>Target Age Group: 18-65 years old</p>\n<h2>Minimum Software/Hardware Requirement</h2>\n<p>Please download and install the following software prior to the class</p>\n<ul>\n<li>Node.js&nbsp; <a href="https://nodejs.org/en/download/" target="_blank">https://nodejs.org/en/download/</a></li>\n<li>Visual Studo Code&nbsp;<a href="https://code.visualstudio.com/download" target="_blank">https://code.visualstudio.com/download</a></li>\n</ul>\n', '5a55d71810c5c3e2f631ba1182507665', ''),
('C605', '<h2>Prerequisite</h2>\n<p>This course is for beginners. No prerequisite is required.</p>\n<h2>Minimum Entry Requirement</h2>\n<p>Knowledge and Skills</p>\n<ul>\n<li>Able to operate using computer functions</li>\n<li>Minimum 3 GCE &lsquo;O&rsquo; Levels Passes including English or WPL Level 5 (Average of Reading, Listening, Speaking &amp; Writing Scores)</li>\n</ul>\n<p>Attitude</p>\n<ul>\n<li>Positive Learning Attitude</li>\n<li>Enthusiastic Learner</li>\n</ul>\n<p>Experience</p>\n<ul>\n<li>Minimum of 1 year of working experience.</li>\n</ul>\n<p>Target Age Group: 21-65 years old</p>\n<h2>Minimum Software/Hardware Requirement</h2>\n<p><strong>Software:</strong></p>\n<p>You will need the following for this course:</p>\n<ul>\n<li>A web browser such as Google Chrome, Microsoft Edge or Safari &ndash; free</li>\n<li>Access to the course materials provided in class</li>\n</ul>\n<p><strong>Hardware:</strong> Windows PC or Mac laptop</p>\n', 'c4dfce1998c6a5a12c5329cedfc3bfe0', ''),
('C610', '<h2>Prerequisite</h2>\n<p>This is a intermediate course. The following knowledge is assumed</p>\n<ul>\n<li>Basic programming</li>\n<li>Basic electronics</li>\n<li>Basic Raspberry Pi</li>\n</ul>\n<h2>Minimum Entry Requirement</h2>\n<p>Knowledge and Skills</p>\n<ul>\n<li>Able to operate using computer functions</li>\n<li>Minimum 3 GCE &lsquo;O&rsquo; Levels Passes including English or WPL Level 5 (Average of Reading, Listening, Speaking &amp; Writing Scores)</li>\n</ul>\n<p>Attitude</p>\n<ul>\n<li>Positive Learning Attitude</li>\n<li>Enthusiastic Learner</li>\n</ul>\n<p>Experience</p>\n<ul>\n<li>Minimum of 1 year of working experience.</li>\n</ul>\n<p>Target Age Group: 18-65 years old</p>\n<h2>Minimum Software/Hardware Requirement</h2>\n<p>Please install the following software prior to the class</p>\n<ul>\n<li><a href="https://www.realvnc.com/en/connect/download/viewer/" title="RealVNC Viewer" target="_blank">RealVNC Viewer</a></li>\n</ul>\n', '8e17413cf6e68ee96ef580ae736a7805', ''),
