('C722', '<h2>Prerequisite</h2>\n<p>This course is for beginners. No prerequisite is required.</p>\n<h2>Minimum Entry Requirement</h2>\n<p>Knowledge and Skills</p>\n<ul>\n<li>Able to operate using computer functions</li>\n<li>Minimum 3 GCE &lsquo;O&rsquo; Levels Passes including English or WPL Level 5 (Average of Reading, Listening, Speaking &amp; Writing Scores)</li>\n</ul>\n<p>Attitude</p>\n<ul>\n<li>Positive Learning Attitude</li>\n<li>Enthusiastic Learner</li>\n</ul>\n<p>Experience</p>\n<ul>\n<li>Minimum of 1 year of working experience.</li>\n</ul>\n<p>Target Age Group: 18-65 years old</p>\n<h2>Minimum Software/Hardware Requirement</h2>\n<p><strong>Software:</strong></p>\n<p>TBD</p>\n<p><strong>Hardware:</strong>&nbsp;Window or Mac Laptops</p>\n', '5fd50c0d3565b26f2fc3b3b913697675', ''),
('C726', '<h2>Prerequisite</h2>\n<p>This course assumes the following:</p>\n<ul>\n<li>Basic Arduino</li>\n<li>Basic C++</li>\n</ul>\n<h2>Minimum Entry Requirement</h2>\n<p>Knowledge and Skills</p>\n<ul>\n<li>Able to operate using computer functions</li>\n<li>Minimum 3 GCE &lsquo;O&rsquo; Levels Passes including English or WPL Level 5 (Average of Reading, Listening, Speaking &amp; Writing Scores)</li>\n</ul>\n<p>Attitude</p>\n<ul>\n<li>Positive Learning Attitude</li>\n<li>Enthusiastic Learner</li>\n</ul>\n<p>Experience</p>\n<ul>\n<li>Minimum of 1 year of working experience.</li>\n</ul>\n<p>Target Age Group: 18-65 years old</p>\n<h2>Minimum Software/Hardware Requirement</h2>\n<ul>\n<li>Download and install Arduino IDE <a href="https://www.arduino.cc/en/Main/Software" title="Arduino IDE" target="_blank">https://www.arduino.cc/en/Main/Software</a></li>\n<li>Download and install Node JS&nbsp;<a href="https://nodejs.org/en/download/" title="Node JS Download" target="_blank">https://nodejs.org/en/download/</a></li>\n</ul>\n</ul>\n', '179df0b94dabfe05d483b1613f2bdb51', ''),
('C728', '<h2>Prerequisite</h2>\n<p>No programming is required - every lab runs in a low-code trading simulator.</p>\n<p>Knowledge and Skills</p>\n<ul>\n<li>Able to operate using computer functions</li>\n<li>A basic understanding of financial markets (stocks, ETFs, buying and selling)</li>\n</ul>\n<p>Attitude</p>\n<ul>\n<li>Positive Learning Attitude</li>\n<li>Enthusiastic Learner</li>\n</ul>\n<p>Experience</p>\n<ul>\n<li>Minimum of 1 year of working experience.</li>\n</ul>\n<h2>Minimum Entry Requirement</h2>\n<p>Knowledge and Skills</p>\n<ul>\n<li>Able to operate using computer functions</li>\n<li>Minimum 3 GCE &lsquo;O&rsquo; Levels Passes including English or WPL Level 5 (Average of Reading, Listening, Speaking &amp; Writing Scores)</li>\n</ul>\n<p>Attitude</p>\n<ul>\n<li>Positive Learning Attitude</li>\n<li>Enthusiastic Learner</li>\n</ul>\n<p>Experience</p>\n<ul>\n<li>Minimum of 1 year of working experience.</li>\n</ul>\n<p>Target Age Group: 18-65 years old</p>\n<h2>Minimum Software/Hardware Requirement</h2>\n<p><strong>Software:</strong></p>\n<p>You will need the following for this course:</p>\n<ul>\n<li>The course <a href="https://github.com/alfredang/algorithmic-trader-bot" target="_blank">Trading Simulator</a> &ndash; free, installed in class with <a href="https://docs.astral.sh/uv/getting-started/installation/" target="_blank">uv</a> or <a href="https://www.docker.com/products/docker-desktop/" target="_blank">Docker Desktop</a></li>\n<li>An <a href="https://alpaca.markets/" target="_blank">Alpaca</a> paper-trading account &ndash; free, no deposit needed</li>\n<li>A <a href="https://www.tradingview.com/" target="_blank">TradingView</a> account &ndash; free plan</li>\n</ul>\n<p><strong>Hardware:</strong> Windows PC or Mac laptop</p>\n', 'deb9d2507b726b93b549f9f03bb5f6fc', ''),
