('C740', '<h2>Prerequisite</h2>\n<p>This course is for beginners. No prerequisite is required.</p>\n<h2>Minimum Entry Requirement</h2>\n<p>Knowledge and Skills</p>\n<ul>\n<li>Able to operate using computer functions</li>\n<li>Minimum 3 GCE &lsquo;O&rsquo; Levels Passes including English or WPL Level 5 (Average of Reading, Listening, Speaking &amp; Writing Scores)</li>\n<li>Experience designing or building LLM-powered applications, with working knowledge of Python or TypeScript and REST APIs</li>\n</ul>\n<p>Attitude</p>\n<ul>\n<li>Positive Learning Attitude</li>\n<li>Enthusiastic Learner</li>\n</ul>\n<p>Experience</p>\n<ul>\n<li>Minimum of 1 year of working experience.</li>\n</ul>\n<p>Target Age Group: 18-65 years old</p>\n<h2>Minimum Software/Hardware Requirement</h2>\n<p><strong>Software:</strong></p>\n<p>You will need the following for this course:</p>\n<ul>\n<li><a href="https://platform.claude.com/" target="_blank">A Claude Developer Platform account with API credits</a> &ndash; required for the Claude API, RAG and MCP labs (pay as you go)</li>\n<li><a href="https://claude.ai/" target="_blank">A Claude Pro (or higher) subscription</a> &ndash; required for Claude Code</li>\n<li><a href="https://www.python.org/downloads/" target="_blank">Python 3.10 or later</a> &ndash; free</li>\n<li><a href="https://nodejs.org/" target="_blank">Node.js (LTS)</a> &ndash; free, for the MCP server labs</li>\n<li><a href="https://code.visualstudio.com/" target="_blank">Visual Studio Code</a> &ndash; free</li>\n</ul>\n<p><strong>Hardware:</strong> Windows PC or Mac laptop</p>\n', '049985416de94929fd7ced24e9f8c7dd', ''),
('C742', '<h2>Prerequisite</h2>\n<p>This course is for beginners. No prerequisite is required.</p>\n<h2>Minimum Entry Requirement</h2>\n<p>Knowledge and Skills</p>\n<ul>\n<li>Able to operate using computer functions</li>\n<li>Minimum 3 GCE &lsquo;O&rsquo; Levels Passes including English or WPL Level 5 (Average of Reading, Listening, Speaking &amp; Writing Scores)</li>\n</ul>\n<p>Attitude</p>\n<ul>\n<li>Positive Learning Attitude</li>\n<li>Enthusiastic Learner</li>\n</ul>\n<p>Experience</p>\n<ul>\n<li>Minimum of 1 year of working experience.</li>\n</ul>\n<p>Target Age Group: 21-65 years old</p>\n<h2>Minimum Software/Hardware Requirement</h2>\n<p><strong>Software:</strong></p>\n<ul>\n<li>Docker Desktop - <a href="https://www.docker.com/products/docker-desktop/" target="_blank">https://www.docker.com/products/docker-desktop/</a></li>\n<li>A local Kubernetes cluster: Minikube (<a href="https://minikube.sigs.k8s.io/docs/start/" target="_blank">https://minikube.sigs.k8s.io/docs/start/</a>) or kind (<a href="https://kind.sigs.k8s.io/" target="_blank">https://kind.sigs.k8s.io/</a>)</li>\n<li>kubectl command line tool - <a href="https://kubernetes.io/docs/tasks/tools/" target="_blank">https://kubernetes.io/docs/tasks/tools/</a></li>\n<li>Visual Studio Code - <a href="https://code.visualstudio.com/" target="_blank">https://code.visualstudio.com/</a></li>\n</ul>\n<p><strong>Hardware:</strong> Windows or Mac laptop with at least 8GB RAM and virtualization enabled</p>\n', '09e7e370ab6d6c877ee514c38fac7c5d', ''),
('C744', '<h2>Prerequisite</h2>\n<p>This course is for beginners. No prerequisite is required.</p>\n<h2>Minimum Entry Requirement</h2>\n<p>Knowledge and Skills</p>\n<ul>\n<li>Able to operate using computer functions</li>\n<li>Minimum 3 GCE &lsquo;O&rsquo; Levels Passes including English or WPL Level 5 (Average of Reading, Listening, Speaking &amp; Writing Scores)</li>\n</ul>\n<p>Attitude</p>\n<ul>\n<li>Positive Learning Attitude</li>\n<li>Enthusiastic Learner</li>\n</ul>\n<p>Experience</p>\n<ul>\n<li>Minimum of 1 year of working experience.</li>\n</ul>\n<p>Target Age Group: 18-65 years old</p>\n<h2>Minimum Software/Hardware Requirement</h2>\n<p><strong>Software:</strong></p>\n<p>You will need the following for this course:</p>\n<ul>\n<li><a href="https://claude.ai/" target="_blank">A Claude Pro (or higher) subscription</a> &ndash; required</li>\n</ul>\n<p><strong>Hardware:</strong> Windows PC or Mac laptop</p>\n', '048840b35eca8e668594f3615e1fe755', ''),
('C746', '<h2>Prerequisite</h2>\n<p>This is a intermediate level course. The following prerequisite is assumed</p>\n<ul>\n<li><a href="https://www.tertiarycourses.com.sg/basic-python-training-for-beginners.html" title="Basic Python Training" target="_blank">Basic Python</a></li>\n</ul>\n<h2>Minimum Entry Requirement</h2>\n<p>Knowledge and Skills</p>\n<ul>\n<li>Able to operate using computer functions</li>\n<li>Minimum 3 GCE &lsquo;O&rsquo; Levels Passes including English or WPL Level 5 (Average of Reading, Listening, Speaking &amp; Writing Scores)</li>\n</ul>\n<p>Attitude</p>\n<ul>\n<li>Positive Learning Attitude</li>\n<li>Enthusiastic Learner</li>\n</ul>\n<p>Experience</p>\n<ul>\n<li>Minimum of 1 year of working experience.</li>\n</ul>\n<p>Target Age Group: 18-65 years old</p>\n<h2>Minimum Software/Hardware Requirement</h2>\n<p>Please download and install the following software prior to the class</p>\n<ul>\n<li>Python 3.x <a href="https://www.python.org/downloads/" title="Python 3" target="_blank">https://www.python.org/downloads/</a></li>\n<li>Sublime Text 3 <a href="https://www.sublimetext.com/3" title="Sublime Text 3" target="_blank">https://www.sublimetext.com/3</a></li>\n<li>Pycharm <a href="https://www.jetbrains.com/pycharm/download/" title="Pycharm" target="_blank">https://www.jetbrains.com/pycharm/download/</a></li>\n</ul>\n', 'eed0f348278417d04f516c52043bda4c', ''),
