('C756', '<h2>Prerequisite</h2>\n<p>This is a intermediate courser. Participants should have basic knowledge on the following subjects:</p>\n<ul>\n<li>C#</li>\n<li>ES6 or Typescript</li>\n</ul>\n<h2>Minimum Entry Requirement</h2>\n<p>Knowledge and Skills</p>\n<ul>\n<li>Able to operate using computer functions</li>\n<li>Minimum 3 GCE &lsquo;O&rsquo; Levels Passes including English or WPL Level 5 (Average of Reading, Listening, Speaking &amp; Writing Scores)</li>\n</ul>\n<p>Attitude</p>\n<ul>\n<li>Positive Learning Attitude</li>\n<li>Enthusiastic Learner</li>\n</ul>\n<p>Experience</p>\n<ul>\n<li>Minimum of 1 year of working experience.</li>\n</ul>\n<p>Target Age Group: 18-65 years old</p>\n<h2>Minimum Software/Hardware Requirement</h2>\n<p><strong>Software:</strong></p>\n<p>You will need the following for this course:</p>\n<ul>\n<li><a href="https://azure.microsoft.com/en-us/pricing/purchase-options/azure-account" target="_blank">A free Microsoft Azure account</a> &ndash; a credit card is required for identity verification</li>\n</ul>\n<p><strong>Hardware:</strong> Windows PC or Mac laptop</p>\n', 'fc14a49bafb0f9dfafcf81424098001e', ''),
('C765', '<h2>Prerequisite</h2>\n<p>This course is for beginners. No prerequisite is required.</p>\n<h2>Minimum Entry Requirement</h2>\n<p>Knowledge and Skills</p><ul><li>Able to operate using computer functions</li><li>Minimum 3 GCE ‘O’ Levels Passes including English or WPL Level 5 (Average of Reading, Listening, Speaking &amp; Writing Scores)</li></ul><p>Attitude</p><ul><li>Positive Learning Attitude</li><li>Enthusiastic Learner</li></ul><p>Experience</p><ul><li>Minimum of 1 year of working experience.</li></ul><p>Target Age Group: 18-65 years old</p>\n<h2>Minimum Software/Hardware Requirement</h2>\n<p><strong>Software:</strong></p>\n<p>You will need the following for this course:</p>\n<ul>\n<li><a href="https://www.python.org/downloads/" target="_blank">Python 3</a> &ndash; free</li>\n<li><a href="https://code.visualstudio.com/download" target="_blank">Visual Studio Code</a> &ndash; free</li>\n<li><a href="https://platform.openai.com/" target="_blank">An OpenAI API account</a> &ndash; pay-as-you-go API credits are required</li>\n</ul>\n<p><strong>Hardware:</strong> Windows PC or Mac laptop</p>\n', 'a939aa3a54ae1651d209c86d7c144da1', ''),
