('C778', '<h2>Prerequisite</h2>\n<p>This course is for beginners. No prerequisite is required.</p>\n<h2>Minimum Entry Requirement</h2>\n<p>Knowledge and Skills</p>\n<ul>\n<li>Able to operate using computer functions</li>\n<li>Minimum 3 GCE &lsquo;O&rsquo; Levels Passes including English or WPL Level 5 (Average of Reading, Listening, Speaking &amp; Writing Scores)</li>\n</ul>\n<p>Attitude</p>\n<ul>\n<li>Positive Learning Attitude</li>\n<li>Enthusiastic Learner</li>\n</ul>\n<p>Experience</p>\n<ul>\n<li>Minimum of 1 year of working experience.</li>\n</ul>\n<p>Target Age Group: 21-65 years old</p>\n<h2>Minimum Software/Hardware Requirement</h2>\n<p><strong>Software:</strong></p>\n<p>You can download and install the following software:</p>\n<ul>\n<li><a href="https://lora-alliance.org/" target="_blank"><span style="text-decoration: underline;">Lora</span></a></li>\n</ul>\n<p><strong>Hardware:</strong> Windows and Mac Laptops</p>\n</ul>\n', '59fe53a34b4075a873aa7d78ae5d3fc9', ''),
('C781', '<h2>Prerequisite</h2>\n<p>This course is for beginners. No prerequisite is required.</p>\n<h2>Minimum Entry Requirement</h2>\n<p>Knowledge and Skills</p>\n<ul>\n<li>Able to operate using computer functions</li>\n<li>Minimum 3 GCE ‘O’ Levels Passes including English or WPL Level 5 (Average of Reading, Listening, Speaking &amp; Writing Scores)</li>\n</ul>\n<p>Attitude</p>\n<ul>\n<li>Positive Learning Attitude</li>\n<li>Enthusiastic Learner</li>\n</ul>\n<p>Experience</p>\n<ul>\n<li>Minimum of 1 year of working experience.</li>\n</ul>\n<p>Target Age Group: 21-65 years old</p>\n<h2>Minimum Software/Hardware Requirement</h2>\n<p><strong>Software:</strong></p>\n<p>You will need the following for this course:</p>\n<ul>\n<li><a href="https://www.microsoft.com/en-us/power-platform/products/power-bi/desktop" target="_blank">Power BI Desktop</a> &ndash; free, Windows only</li>\n</ul>\n<p><strong>Hardware:</strong> Windows PC or laptop (Power BI Desktop runs on Windows only)</p>\n', '420a214e6d227768aa4f93b0962f0533', ''),
('C782', '<h2>Prerequisite</h2>\n<p>This is an intermediate course. The following knowledge is assumed:</p>\n<ul>\n<li>Basic Python</li>\n</ul>\n<h2>Minimum Entry Requirement</h2>\n<p>Knowledge and Skills</p>\n<ul>\n<li>Able to operate using computer functions</li>\n<li>Minimum 3 GCE &lsquo;O&rsquo; Levels Passes including English or WPL Level 5 (Average of Reading, Listening, Speaking &amp; Writing Scores)</li>\n</ul>\n<p>Attitude</p>\n<ul>\n<li>Positive Learning Attitude</li>\n<li>Enthusiastic Learner</li>\n</ul>\n<p>Experience</p>\n<ul>\n<li>Minimum of 1 year of working experience.</li>\n</ul>\n<p>Target Age Group: 18-65 years old</p>\n<h2>Minimum Software/Hardware Requirement</h2>\n<p>Please install the following software prior to the class</p>\n<p>1. Pycharm :&nbsp;Install Pycharm (<a href="https://www.jetbrains.com/pycharm/download/" target="_blank">https://www.jetbrains.com/pycharm/download/</a>)</p>\n<pInstall Tensorflow on Mac</p>\n<p>2. Please follow this guide to install Tensorflow on Mac&nbsp;h<a href="ttps://www.tensorflow.org/install/install_mac" target="_blank">ttps://www.tensorflow.org/install/install_mac</a></p>\n<p>Alternatively, you can enter the following commands on your Mac terminal</p>\n<p>pip3 install tensorflow</p>\n<p>3 . Install Tensorflow on Window</p>\n<p>Please follow this guide to install Tensorflow on Window <a href="https://www.tensorflow.org/install/install_windows" target="_blank">https://www.tensorflow.org/install/install_windows</a></p>\n<p>Tensorflow only support Python 3.5, you can install Tensorflow in Python 3.5 the following ways:</p>\n<ul>\n<li>Install Anaconda for Windows <a href="https://www.anaconda.com/download/#windows" target="_blank">https://www.anaconda.com/download/#windows</a></li>\n<li>Create a new Conda environment in Pycharm for Python 3.5</li>\n</ul>\n', 'bc4b1d299641bdd70c6cb53860efc991', '');
INSERT INTO tmp_prereq_std (sku, val, md5_0, md5_ov) VALUES
('C785', '<h2>Prerequisite</h2>\n<p>This course is for beginners. No prerequisite is required.</p>\n<h2>Minimum Entry Requirement</h2>\n<p>Knowledge and Skills</p>\n<ul>\n<li>Able to operate using computer functions&nbsp;<span>with minimum Computer Literacy Level 2 based on ICAS Computer Skills Assessment Framework</span></li>\n<li>Minimum 3 GCE &lsquo;O&rsquo; Levels Passes including English or WPL Level 5 (Average of Reading, Listening, Speaking &amp; Writing Scores)</li>\n</ul>\n<p>Attitude</p>\n<ul>\n<li>Positive Learning Attitude</li>\n<li>Enthusiastic Learner</li>\n</ul>\n<p>Experience</p>\n<ul>\n<li>Minimum of 1 year of working experience.</li>\n</ul>\n<p>Target Age Group: 21-65 years old</p>\n<h2>Minimum Software/Hardware Requirement</h2>\n<p><strong>Software:</strong> NIL</p>\n<p><strong>Hardware:</strong>&nbsp;Windows and Mac Laptops</p>\n', 'a298d7d2b77c0756c00976206008da22', ''),
