UPDATE catalog_product_entity_text t
  JOIN catalog_product_entity e ON e.entity_id = t.entity_id
  JOIN tmp_prereq_std s ON s.sku = TRIM(e.sku)
   SET t.value = s.val
 WHERE @ok AND t.attribute_id = @a AND t.store_id = 0 AND (s.md5_0 = '' OR MD5(t.value) = s.md5_0);

INSERT INTO catalog_product_entity_text (entity_type_id, attribute_id, store_id, entity_id, value)
SELECT 4, @a, 0, e.entity_id, s.val
  FROM tmp_prereq_std s JOIN catalog_product_entity e ON TRIM(e.sku) = s.sku
 WHERE @ok AND s.md5_0 = ''
   AND NOT EXISTS (SELECT 1 FROM catalog_product_entity_text x WHERE x.entity_id = e.entity_id AND x.attribute_id = @a AND x.store_id = 0);

-- store-level overrides that still hold the exported value, once the default carries the new value: removed
DELETE t FROM catalog_product_entity_text t
  JOIN catalog_product_entity e ON e.entity_id = t.entity_id
  JOIN tmp_prereq_std s ON s.sku = TRIM(e.sku)
  JOIN catalog_product_entity_text d ON d.entity_id = t.entity_id AND d.attribute_id = t.attribute_id AND d.store_id = 0
 WHERE @ok AND t.attribute_id = @a AND t.store_id <> 0 AND s.md5_ov <> '' AND MD5(t.value) = s.md5_ov
   AND d.value = s.val;

DROP TEMPORARY TABLE IF EXISTS tmp_prereq_std;
